import csv,json,unicodedata
from pathlib import Path
from etymology_assignments import read_assignments
P=Path('curation/etymology-lab/indo-aryan-diversity-20260922')
linked={r['Form_ID'] for r in read_assignments() if r['Status']=='accepted'};linked.update(r['Child_ID'] for r in csv.DictReader(open('cldf/edges.csv')) if r['Rank']=='1')
rs=[r for r in json.loads((P/'schmidt-poguli-siraji-remaining057.json').read_text()) if r['ID'] not in linked]
groups=[('beard',['də̄ṛ','dāṛī́'],'6250','*dāṁṣṭra','Turner6250 explicitly groups Kashmiri dör and regional dāṛī beard with MIA dāṭhikā/dāḍhiā. Poguli central-vowel də̄ṛ and Siraji dāṛī́ fit those regional outcomes. Turner discusses competing explanations of the deeper cluster and possible Dravidian/Munda influence; this link retains that uncertainty.'),('bone',['aḍʸe','haḍī́'],'13952','haḍḍa','Turner13952 gives Kashmiri aḍa bones, aḍyul large bone and aḍij small bone alongside regional haḍḍī. These support Poguli’s h-less palatalised aḍʸe and Siraji haḍī́ in the same bone family. The source ending and palatalisation are preserved, without assigning a number not specified by the table; Turner doubts a connection with asthi.'),('eye',['aś','acʰʸ'],'43','akṣi','Turner43 gives Kashmiri achi, Rambani acch and Kishtawari acchī alongside the regional aṣī-type sibilant outcome. These support Poguli aś and Siraji acʰʸ as eye-family reflexes; palatalisation and the source distinction between ś and aspirated c remain intact.'),('finger',['anglʸe','ãŋglī́'],'135','aṅguli','Turner135 section1 contains Kashmiri onguj, Bhalessi aṅgoli and contracted regional uṅglī/ā̃gḷī forms. Poguli anglʸe and Siraji ãŋglī́ retain the lateral of this branch, rather than selecting section2 aṅgūḍi. Preserve the source ending, nasalisation, stress and palatalisation.'),('fingernail',['nam'],'6914','nakha','Turner6914 section1 explicitly gives Kashmiri nam nail under early nasalisation, querying an intermediate *naṅg. Both table nam responses match that distinctive regional form; the proposed intermediate remains uncertain, and these are not the geminate-nakkha subsection.'),('flesh',['māz','mās'],'9982','māṁsa','Turner9982 explicitly gives Kashmiri māz/mās flesh or meat and neighbouring Pahari mās. Poguli māz and Siraji mās match these voiced and voiceless regional outcomes; no meaning or source pronunciation is normalised.'),('hand',['āht','hat'],'14024','hasta','Turner14024 explicitly gives Poguli āht hand and neighbouring Pahari hat/hatth. This directly supports the table’s Poguli metathesised form and Siraji hat, with their distinct consonant order and vowel quantity preserved.')]
a=[];audit=[];source=list(csv.DictReader(open('data/other/forms/raw_data/schmidt_kashmiri.csv')));raw=list(csv.reader(open('data/other/forms/20260725-schmidt-kashmiri.csv')))
lines=['# Schmidt and Kaul: Poguli and Siraji body vocabulary','','Fourteen reflex records across seven families; standing autonomous authorization. Table 3, printed pp. 283–284 (PDF pp. 53–54), visually checked.','','| # | Poguli / Siraji forms and meaning | Proposed etymology | Evidence |','|---|---|---|---|']
for i,(g,fs,parent,label,ev) in enumerate(groups,1):
 hits=[r for r in rs if r['Gloss']==g and r['Form'] in fs];assert len(hits)==2,(g,len(hits))
 for r in hits:
  rr=[z for z in raw if z[0]==r['Language_ID'] and z[2]==r['Original'] and z[3]==g and z[6]==r['Description']];assert len(rr)==1,(r,rr)
  item=r['Description'].split()[-1];sr=next(z for z in source if z['Item']==item)
  col={'pog':'Poguli','sir':'Siraji'}[r['Language_ID']];assert unicodedata.normalize('NFC',sr[col])==r['Original']
  page=283 if int(item)<=13 else 284
  citation=f'schmidt[p. {page}, Table 3, item {item}];CDIAL[{parent} and addenda]'
  a.append(dict(record={k:r[k] for k in ['ID','Language_ID','Form','Gloss','Source','Tags']},parent=parent,kind='reflex',citation=citation,evidence=ev+' Source image and reviewed import row checked; no source transcription or identity changes.'))
  audit.append(dict(record_id=r['ID'],reviewed_source_row=sr,import_row=rr[0],printed_page=page,image=f'../tmp/pdfs/schmidt_kaul_2008/boundary150/page-{sr["Page"]}.png',visual_check='confirmed'))
 label=label.replace('*',r'\*');lines.append(f'| {i} | **{" / ".join(fs)}** ‘{g}’ (2) | **{label}**, CDIAL **{parent}** | {ev} |')
h=[dict(record=r,reason='Poguli īḍ and Siraji iḍ belly need source-specific historical evidence. Search resemblance to ḍhiḍḍha does not explain the absent initial consonant; do not force that family.') for r in rs if r['Gloss']=='belly']
assert len(a)==14 and len(h)==2
for name,val in [('decisions',dict(accepted=a,held=h)),('source-audit',audit)]: (P/f'pass057-{name}.json').write_text(json.dumps(val,ensure_ascii=False,indent=2)+'\n')
lines+=['','Two belly records held: **īḍ / iḍ**. Search candidates do not yet explain their initial-vowel shapes.','','Discovery: schmidt-search001–002. Full primary articles and separately numbered addenda: schmidt-primary001–003. No rebuild.','','Save and validation pending.'];(P/'pass057-review.md').write_text('\n'.join(lines)+'\n');print(len(a),'accepted',len(h),'held')
